"""Page presenters; data and action helpers supplied by the runtime."""
from __future__ import annotations
from .. import ember_workbench as runtime

def library_document_viewer_html(task_id: str, delivery_key: str, relative_path: str) -> str | None:
    payload = runtime.library_file_preview_payload(task_id, delivery_key, relative_path)
    if not payload or payload.get("preview_kind") != "document":
        return None
    title = runtime.html.escape(str(payload.get("name") or "文档预览"))
    label = runtime.html.escape(str(payload.get("document_label") or "文档"))
    error = str(payload.get("preview_error") or "")
    pages = int(payload.get("page_count") or 0)
    if error or not pages:
        message = runtime.html.escape(error or "文件没有可显示的页面。")
        return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>*{{box-sizing:border-box}}html,body{{width:100%;height:100%;margin:0}}body{{display:grid;place-content:center;padding:28px;background:#eef1f5;color:#667085;font:13px/1.6 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;text-align:center}}strong{{display:block;margin-bottom:7px;color:#111827;font-size:15px}}span{{display:block;max-width:480px}}</style></head><body><div><strong>{label} 暂时无法预览</strong><span>{message}<br>请返回工作台，使用系统应用打开。</span></div></body></html>'''
    page_url = str(payload.get("page_url") or "")
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>
*{{box-sizing:border-box}}html,body{{width:100%;height:100%;margin:0}}body{{display:flex;min-height:100%;flex-direction:column;overflow:hidden;background:#e9edf2;color:#111827;font:13px/1.4 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}}button{{font:inherit}}.toolbar{{z-index:2;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:10px;min-height:46px;padding:7px 10px;border-bottom:1px solid #d8dee7;background:rgba(255,255,255,.97);box-shadow:0 1px 4px rgba(15,23,42,.06)}}.group{{display:flex;align-items:center;gap:5px}}.group:last-child{{justify-content:flex-end}}button{{display:inline-flex;min-width:30px;height:30px;align-items:center;justify-content:center;padding:0 8px;border:1px solid transparent;border-radius:6px;background:transparent;color:#374151;font-size:12px;font-weight:750;cursor:pointer}}button:hover:not(:disabled){{border-color:#e5e7eb;background:#f3f4f6;color:#111827}}button:disabled{{opacity:.28;cursor:not-allowed}}.counter,.zoom-label{{min-width:54px;color:#6b7280;font-size:10px;font-variant-numeric:tabular-nums;text-align:center}}.counter strong{{color:#111827}}.kind{{display:inline-flex;align-items:center;gap:6px;padding:4px 9px;border-radius:999px;background:#eef2ff;color:#3730a3;font-size:9px;font-weight:800;letter-spacing:.04em}}.kind::before{{content:"";width:5px;height:5px;border-radius:50%;background:#6366f1}}.canvas{{min-height:0;flex:1;overflow:auto;padding:22px 24px 34px;overscroll-behavior:contain;outline:none}}.page-wrap{{width:auto;margin:0 auto;transition:width .15s ease}}img{{display:block;width:100%;height:auto;border-radius:2px;background:#fff;box-shadow:0 7px 24px rgba(15,23,42,.16)}}img.loading{{min-height:0;opacity:.45}}@media(max-width:640px){{.toolbar{{grid-template-columns:1fr auto}}.kind{{display:none}}.canvas{{padding:12px 10px 24px}}button{{min-width:28px;padding:0 6px}}.zoom-label{{min-width:42px}}}}
</style></head><body><div class="toolbar"><div class="group"><button id="prev" type="button" aria-label="上一页">‹</button><span class="counter"><strong id="current">1</strong> / {pages}</span><button id="next" type="button" aria-label="下一页">›</button></div><span class="kind">{label}</span><div class="group"><button id="zoomOut" type="button" aria-label="缩小">−</button><span class="zoom-label" id="zoomLabel">适合页面</span><button id="zoomIn" type="button" aria-label="放大">＋</button><button id="fit" type="button">适页</button></div></div><div class="canvas" id="canvas" tabindex="0"><div class="page-wrap" id="pageWrap"><img id="page" class="loading" src="{runtime.html.escape(page_url, quote=True)}1" alt="{title} 第 1 页"></div></div><script>
(()=>{{const total={pages},base={runtime.json.dumps(page_url)},image=document.getElementById('page'),canvas=document.getElementById('canvas'),wrap=document.getElementById('pageWrap'),current=document.getElementById('current'),prev=document.getElementById('prev'),next=document.getElementById('next'),zoomLabel=document.getElementById('zoomLabel');let page=1,zoom=100,fitWidth=0;function show(target){{page=Math.max(1,Math.min(total,target));current.textContent=page;prev.disabled=page===1;next.disabled=page===total;image.classList.add('loading');image.src=base+page;image.alt=`第 ${{page}} 页`;canvas.scrollTo({{top:0,left:0,behavior:'smooth'}})}}function resize(target){{zoom=Math.max(50,Math.min(200,target));wrap.style.width=fitWidth?`${{Math.round(fitWidth*zoom/100)}}px`:`min(${{zoom}}%, ${{Math.round(1120*zoom/100)}}px)`;zoomLabel.textContent=zoom===100?'适合页面':zoom+'%'}}function fitPage(){{if(!image.naturalWidth||!image.naturalHeight)return;const style=getComputedStyle(canvas),availableWidth=canvas.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight),availableHeight=canvas.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom);fitWidth=Math.max(1,Math.min(1120,availableWidth,availableHeight*image.naturalWidth/image.naturalHeight));resize(zoom)}}image.addEventListener('load',()=>{{image.classList.remove('loading');fitPage()}});image.addEventListener('error',()=>image.classList.remove('loading'));prev.onclick=()=>show(page-1);next.onclick=()=>show(page+1);document.getElementById('zoomOut').onclick=()=>resize(zoom-25);document.getElementById('zoomIn').onclick=()=>resize(zoom+25);document.getElementById('fit').onclick=()=>resize(100);canvas.addEventListener('keydown',event=>{{if(event.key==='ArrowLeft'){{event.preventDefault();show(page-1)}}else if(event.key==='ArrowRight'){{event.preventDefault();show(page+1)}}}});new ResizeObserver(fitPage).observe(canvas);show(1);resize(100)}})();
</script></body></html>'''


def _render_library_legacy(token: str, notice: str = "", error: str = "") -> str:
    """Render the read-only task and delivery browser."""
    records = runtime.library_task_records()
    projects = runtime.project_items()
    payload: list[dict[str, object]] = []
    choices: list[str] = []
    for index, record in enumerate(records):
        task_id = str(record.get("task_id") or "")
        title = str(record.get("task_name") or record.get("title") or task_id)
        group_tag = runtime.task_group_tag(record)
        project = str(record.get("project") or "")
        project_title = runtime.task_scope_title(project, str(record.get("project_title") or ""))
        status = str(record.get("status") or "")
        work_type = str(record.get("work_type") or "")
        delivery = record.get("library_delivery") if isinstance(record.get("library_delivery"), dict) else {}
        delivery_key = str(delivery.get("key") or "")
        delivery_count = runtime.library_delivery_file_count({str(key): str(value) for key, value in delivery.items()})
        delivery_count_label = f"{delivery_count} 个交付文件" if delivery_count is not None else "点击读取交付文件"
        search_text = runtime.task_search_summary(record)
        search_encoded = runtime.base64.b64encode(search_text.lower().encode("utf-8")).decode("ascii")
        payload.append({
            "task_id": task_id,
            "title": title,
            "project": project,
            "project_title": project_title,
            "status": status,
            "status_label": runtime.STATUS_LABEL.get(status, status),
            "work_type": work_type,
            "type_label": runtime.TYPE_LABEL.get(work_type, work_type),
            "source_name": str(record.get("library_source_name") or f"{task_id}.md"),
            "delivery_key": delivery_key,
            "delivery_name": str(delivery.get("name") or ""),
            "delivery_count": delivery_count,
        })
        choices.append(
            f'<div class="library-task-choice" data-library-task-choice data-task-id="{runtime.html.escape(task_id, quote=True)}" data-project="{runtime.html.escape(project, quote=True)}" data-type="{runtime.html.escape(work_type, quote=True)}" data-status="{runtime.html.escape(status, quote=True)}" data-delivery="{ "yes" if delivery_count else "no"}" data-search="{search_encoded}">'
            f'<label class="library-pin-source" title="固定来源"><input type="checkbox" value="{runtime.html.escape(task_id, quote=True)}" aria-label="固定来源：{runtime.html.escape(title, quote=True)}"></label><button class="library-task-choice-main" type="button" data-library-left-preview="{runtime.html.escape(task_id, quote=True)}"><span class="library-task-title">{runtime.html.escape(title)}{group_tag}</span><span class="library-task-meta">{runtime.html.escape(project_title)} · {runtime.html.escape(delivery_count_label)}</span></button>'
            f'<span class="badge {runtime.html.escape(status, quote=True)}">{runtime.html.escape(runtime.STATUS_LABEL.get(status, status))}</span></div>'
        )
    type_values = sorted({str(item.get("work_type") or "") for item in records if item.get("work_type")})
    status_values = [value for value in runtime.STATUS_LABEL if any(str(item.get("status") or "") == value for item in records)]
    def filter_menu(identifier: str, label: str, options: list[tuple[str, str]]) -> str:
        items = "".join(
            f'<label><input type="checkbox" value="{runtime.html.escape(value, quote=True)}"><span>{runtime.html.escape(text)}</span></label>'
            for value, text in options
        )
        return f'<details class="library-multi-filter" data-library-filter="{identifier}" data-label="{runtime.html.escape(label, quote=True)}"><summary>{runtime.html.escape(label)}</summary><div class="library-multi-filter-menu">{items}</div></details>'
    project_slugs = {str(item.get("project") or "") for item in records}
    ordered_project_slugs = [slug for slug in runtime.formal_project_slugs() if slug in project_slugs]
    ordered_project_slugs.extend(sorted(project_slugs - set(ordered_project_slugs)))
    project_filter = filter_menu(
        "project",
        "全部项目",
        [(slug, runtime.task_scope_title(slug)) for slug in ordered_project_slugs if slug],
    )
    type_filter = filter_menu("type", "全部类型", [(value, runtime.TYPE_LABEL.get(value, value)) for value in type_values])
    status_filter = filter_menu("status", "全部状态", [(value, runtime.STATUS_LABEL[value]) for value in status_values])
    delivery_filter = filter_menu("delivery", "全部交付", [("yes", "有交付物"), ("no", "无交付物")])
    data_json = runtime.json.dumps(payload, ensure_ascii=False).replace("</", "<\\/")
    csrf_json = runtime.json.dumps(token, ensure_ascii=False)
    message = runtime.flash_message(notice, error)
    content = rf'''{message}
    <div class="library-layout">
      <section class="panel library-column library-filter-column"><div class="library-column-head"><h1>选择任务</h1><button class="button ghost" id="libraryClearSelection" type="button">清空</button></div><div class="library-filter-stack"><p class="library-source-helper">点击任务临时预览；勾选后可固定多个来源。</p><div class="search-wrap"><span class="search-icon">⌕</span><input id="libraryTaskSearch" type="search" placeholder="搜索任务卡内容" aria-label="搜索任务卡"></div><div class="library-filter-row">{project_filter}{type_filter}</div><div class="library-filter-row">{status_filter}{delivery_filter}</div></div><div class="library-task-list" id="libraryTaskList">{''.join(choices) if choices else '<div class="library-empty">暂无任务卡</div>'}</div><div class="library-selection-meta" id="librarySelectionMeta">已选 0 项 · 最多 50 项</div></section>
      <section class="panel library-column"><div class="library-column-head"><h2>相关文件</h2><span class="meta" id="libraryGroupCount"></span></div><div class="library-ai-panel"><strong>用所选交付文件开启二次任务</strong><p>可跨任务多选；自动附上来源任务卡和文件路径，原文件保持只读。</p><div class="library-ai-actions"><form method="post" action="/actions/revise-library-files" data-library-revise-form data-execution-confirm data-execution-label="交付文件二次处理"><input type="hidden" name="csrf" value="{runtime.html.escape(token, quote=True)}"><input type="hidden" name="return_to" value="/library">{runtime.execution_confirm_button("核对所选文件并开始二次处理", disabled=True)}</form></div><span class="library-file-selection-meta" id="libraryFileSelectionMeta">已选 0 个交付文件</span></div><div class="library-groups" id="libraryGroups"><div class="library-empty">请先选择任务卡。</div></div></section>
      <section class="panel library-column library-preview-column"><div class="library-preview-stack" id="libraryPreviewStack"><section class="library-preview-pane library-task-pane"><div class="library-preview-pane-head"><strong id="libraryTaskPreviewTitle">任务卡预览</strong><div class="library-preview-pane-actions"><a class="button ghost" id="libraryTaskDetail" href="/">完整任务</a><button class="button ghost" id="libraryExpandTask" type="button">展开</button></div></div><div class="library-preview-body article md" id="libraryTaskPreview"><div class="library-preview-placeholder">选择中间栏的任务卡或交付文件。</div></div></section><div class="library-preview-divider" id="libraryPreviewDivider" role="separator" aria-label="调整上下预览高度" aria-orientation="horizontal" tabindex="0"></div><section class="library-preview-pane library-file-pane"><div class="library-preview-pane-head"><strong id="libraryFilePreviewTitle">交付文件预览</strong><div class="library-preview-pane-actions"><button class="button ghost" id="libraryExpandFile" type="button">展开</button></div></div><div class="library-preview-body" id="libraryFilePreview"><div class="library-preview-placeholder">选择交付文件。</div></div></section></div></section>
    </div>
    <script id="libraryData" type="application/json">{data_json}</script><script>(()=>{{
      const params=new URLSearchParams(location.search),tasks=JSON.parse(document.getElementById('libraryData').textContent),taskMap=new Map(tasks.map(item=>[item.task_id,item])),csrf={csrf_json};
      const choices=[...document.querySelectorAll('[data-library-task-choice]')],search=document.getElementById('libraryTaskSearch'),filters=[...document.querySelectorAll('[data-library-filter]')],groups=document.getElementById('libraryGroups'),selectionMeta=document.getElementById('librarySelectionMeta'),groupCount=document.getElementById('libraryGroupCount'),taskTitle=document.getElementById('libraryTaskPreviewTitle'),taskBody=document.getElementById('libraryTaskPreview'),taskDetail=document.getElementById('libraryTaskDetail'),fileTitle=document.getElementById('libraryFilePreviewTitle'),fileBody=document.getElementById('libraryFilePreview'),stack=document.getElementById('libraryPreviewStack'),divider=document.getElementById('libraryPreviewDivider'),fileSelectionMeta=document.getElementById('libraryFileSelectionMeta'),reviseForms=[...document.querySelectorAll('[data-library-revise-form]')];
      const esc=value=>String(value??'').replace(/[&<>\"]/g,char=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}}[char]));
      const decode=value=>new TextDecoder().decode(Uint8Array.from(atob(value||''),character=>character.charCodeAt(0)));
      const normalizeSearch=value=>String(value??'').normalize('NFKC').toLowerCase().replace(/[\u200B-\u200D\uFEFF]/g,'').replace(/[‐‑‒–—―﹘﹣－]/g,'-').trim();
      const compactSearch=value=>normalizeSearch(value).replace(/[\s\-_.·,，。:：;；/\\|()[\]{{}}《》【】'"“”‘’]+/g,'');
      function fuzzyContains(document,term){{if(document.includes(term))return true;const haystack=compactSearch(document),needle=compactSearch(term);if(!needle)return true;if(haystack.includes(needle))return true;if(needle.length<2)return false;let first=-1,position=-1;for(const character of needle){{position=haystack.indexOf(character,position+1);if(position<0)return false;if(first<0)first=position}}return position-first+1<=Math.max(needle.length*4,needle.length+10)}}
      let focusedTaskId='',remoteMatches=null,searchTimer=0,searchRequest=0;
      const selected=()=>choices.filter(choice=>choice.querySelector('input').checked).map(choice=>choice.querySelector('input').value);
      const displayed=()=>{{const ids=selected();if(focusedTaskId&&!ids.includes(focusedTaskId))ids.push(focusedTaskId);return ids}};
      const icon=entry=>entry.is_dir?'▸':entry.suffix==='.md'?'M':['.png','.jpg','.jpeg','.webp','.gif'].includes(entry.suffix)?'◇':['.mp4','.mov','.m4v','.webm'].includes(entry.suffix)?'▶':entry.suffix==='.pdf'?'P':'·';
      const filterValues=filter=>[...filter.querySelectorAll('input:checked')].map(input=>input.value);
      search.value=params.get('q')||'';filters.forEach(filter=>{{const values=new Set((params.get(`f_${{filter.dataset.libraryFilter}}`)||'').split(',').filter(Boolean));filter.querySelectorAll('input').forEach(input=>input.checked=values.has(input.value))}});
      function syncUrl(){{const next=new URLSearchParams(location.search);search.value.trim()?next.set('q',search.value.trim()):next.delete('q');filters.forEach(filter=>{{const key=`f_${{filter.dataset.libraryFilter}}`,values=filterValues(filter);values.length?next.set(key,values.join(',')):next.delete(key)}});history.replaceState(null,'',location.pathname+(next.size?'?'+next:''))}}
      function updateFilterLabel(filter){{const values=filterValues(filter),label=filter.dataset.label;filter.querySelector('summary').textContent=values.length?`${{label.replace('全部','')}} · ${{values.length}}项`:label}}
      function filterTasks(){{const terms=normalizeSearch(search.value).split(/\s+/).filter(Boolean);choices.forEach(choice=>{{const document=normalizeSearch(decode(choice.dataset.search)),filterMatch=filters.every(filter=>{{const values=filterValues(filter);return !values.length||values.includes(choice.dataset[filter.dataset.libraryFilter])}}),textMatch=!terms.length||(remoteMatches?remoteMatches.has(choice.dataset.taskId):terms.every(term=>fuzzyContains(document,term))),match=textMatch&&filterMatch;choice.style.display=match?'':'none'}});syncUrl()}}
      async function searchRemote(){{const query=search.value.trim(),request=++searchRequest;if(!query){{remoteMatches=null;filterTasks();return}}try{{const response=await fetch('/api/tasks/search?q='+encodeURIComponent(query),{{headers:{{Accept:'application/json'}}}});if(!response.ok)throw new Error();const data=await response.json();if(request!==searchRequest)return;remoteMatches=new Set((data.items||[]).map(item=>item.task_id));filterTasks()}}catch(error){{if(request===searchRequest)remoteMatches=null}}}}
      function scheduleSearch(){{remoteMatches=null;filterTasks();clearTimeout(searchTimer);searchTimer=setTimeout(searchRemote,180)}}
      function taskNode(item){{return `<button class="library-node" type="button" data-library-task-node="${{esc(item.task_id)}}"><span class="library-node-icon">M</span><span class="library-node-name">${{esc(item.source_name)}}</span></button>`}}
      function bindGroup(group,item){{group.querySelector('[data-library-task-node]')?.addEventListener('click',event=>{{markActive(event.currentTarget);previewTask(item.task_id)}});if(item.delivery_key)loadFlatFiles(item,group)}}
      function renderGroups(){{const selectedIds=selected(),ids=displayed();selectionMeta.textContent=`已选 ${{selectedIds.length}} 项 · 最多 50 项`;choices.forEach(choice=>choice.classList.toggle('selected',choice.querySelector('input').checked));groupCount.textContent=ids.length?`${{ids.length}} 个任务`:'';if(!ids.length){{groups.innerHTML='<div class="library-empty">点击任务可临时查看，勾选后持续保留。</div>';updateFileSelection();return}}groups.innerHTML=ids.map(id=>{{const item=taskMap.get(id);return `<section class="library-group" data-library-group="${{esc(id)}}"><div class="library-group-title">${{esc(item.title)}}</div><div class="library-group-body">${{taskNode(item)}}${{item.delivery_key?'<div class="library-node-empty">正在读取交付文件…</div>':''}}</div></section>`}}).join('');ids.forEach(id=>bindGroup(groups.querySelector(`[data-library-group="${{CSS.escape(id)}}"]`),taskMap.get(id)));updateFileSelection();previewTask(focusedTaskId||ids[0])}}
      function markActive(node){{document.querySelectorAll('.library-node.active').forEach(item=>item.classList.remove('active'));node?.classList.add('active')}}
      async function previewTask(taskId,resetFile=true){{const item=taskMap.get(taskId);taskTitle.textContent=item?.title||'任务卡预览';taskDetail.href=`/tasks/${{encodeURIComponent(taskId)}}`;if(resetFile){{fileTitle.textContent='交付文件预览';fileBody.innerHTML='<div class="library-preview-placeholder">从中栏选择关联交付文件。</div>'}}taskBody.innerHTML='<div class="library-preview-placeholder">正在加载任务卡…</div>';try{{const response=await fetch(`/api/tasks/${{encodeURIComponent(taskId)}}/preview`);if(!response.ok)throw new Error();const data=await response.json();taskBody.innerHTML=data.body_html||'<div class="library-preview-placeholder">任务卡正文为空。</div>'}}catch(error){{taskBody.innerHTML='<div class="library-preview-placeholder">暂时无法读取任务卡。</div>'}}}}
      function updateFileSelection(){{const checked=[...document.querySelectorAll('[data-library-file-check]:checked')],values=checked.map(input=>input.value);fileSelectionMeta.textContent=`已选 ${{values.length}} 个交付文件`;reviseForms.forEach(form=>{{form.querySelectorAll('input[name="selection"]').forEach(input=>input.remove());values.forEach(value=>{{const input=document.createElement('input');input.type='hidden';input.name='selection';input.value=value;form.appendChild(input)}});form.querySelector('button').disabled=!values.length}})}}
      async function loadFlatFiles(item,group){{const body=group.querySelector('.library-group-body');try{{const response=await fetch(`/api/library/directory?task_id=${{encodeURIComponent(item.task_id)}}&delivery=${{encodeURIComponent(item.delivery_key)}}&flat=1`);if(!response.ok)throw new Error();const data=await response.json();body.innerHTML=taskNode(item)+(data.entries.length?data.entries.map(entry=>`<div class="library-node file-selectable"><input type="checkbox" data-library-file-check value="${{esc(JSON.stringify({{task_id:item.task_id,delivery:item.delivery_key,path:entry.relative_path}}))}}" aria-label="选择 ${{esc(entry.name)}}"><span class="library-node-icon">${{icon(entry)}}</span><button class="library-node-name" type="button" data-library-flat-preview="${{esc(entry.relative_path)}}" title="${{esc(entry.relative_path)}}">${{esc(entry.name)}}</button></div>`).join(''):'');body.querySelector('[data-library-task-node]').addEventListener('click',event=>{{markActive(event.currentTarget);previewTask(item.task_id)}});body.querySelectorAll('[data-library-file-check]').forEach(input=>input.addEventListener('change',updateFileSelection));body.querySelectorAll('[data-library-flat-preview]').forEach(node=>node.addEventListener('click',()=>{{markActive(node.closest('.library-node'));previewFile(item.task_id,item.delivery_key,node.dataset.libraryFlatPreview,group)}}));updateFileSelection()}}catch(error){{body.innerHTML=taskNode(item)+'<div class="library-node-empty">暂时无法读取交付文件。</div>'}}}}
      async function loadDirectory(taskId,delivery,current,group){{previewTask(taskId,false);fileTitle.textContent=current.split('/').pop()||taskMap.get(taskId)?.delivery_name||'交付文件';fileBody.innerHTML='<div class="library-preview-placeholder">从中栏选择要预览的文件。</div>';const url=`/api/library/directory?task_id=${{encodeURIComponent(taskId)}}&delivery=${{encodeURIComponent(delivery)}}&path=${{encodeURIComponent(current)}}`;try{{const response=await fetch(url);if(!response.ok)throw new Error();const data=await response.json(),item=taskMap.get(taskId),body=group.querySelector('.library-group-body'),parent=current.includes('/')?current.split('/').slice(0,-1).join('/'):'';body.innerHTML=taskNode(item)+`<div class="library-directory-nav"><button type="button" data-library-back>‹</button><span>${{esc(current||item.delivery_name)}}</span></div>`+(data.entries.length?data.entries.map(entry=>`<button class="library-node" type="button" data-library-entry="${{esc(entry.relative_path)}}" data-is-dir="${{entry.is_dir?'1':'0'}}"><span class="library-node-icon">${{icon(entry)}}</span><span class="library-node-name">${{esc(entry.name)}}</span></button>`).join(''):'<div class="library-node-empty">文件夹为空</div>');body.querySelector('[data-library-task-node]').addEventListener('click',event=>{{markActive(event.currentTarget);previewTask(taskId)}});body.querySelector('[data-library-back]').addEventListener('click',()=>current?loadDirectory(taskId,delivery,parent,group):renderGroups());body.querySelectorAll('[data-library-entry]').forEach(node=>node.addEventListener('click',()=>{{markActive(node);node.dataset.isDir==='1'?loadDirectory(taskId,delivery,node.dataset.libraryEntry,group):previewFile(taskId,delivery,node.dataset.libraryEntry,group)}}))}}catch(error){{fileBody.innerHTML='<div class="library-preview-placeholder">暂时无法读取交付文件夹。</div>'}}}}
      function actionForm(taskId,delivery,path,mode,label){{return `<form method="post" action="/actions/open-library-item"><input type="hidden" name="csrf" value="${{esc(csrf)}}"><input type="hidden" name="return_to" value="/library"><input type="hidden" name="task_id" value="${{esc(taskId)}}"><input type="hidden" name="delivery" value="${{esc(delivery)}}"><input type="hidden" name="path" value="${{esc(path)}}"><input type="hidden" name="mode" value="${{esc(mode)}}"><button class="button" type="submit">${{esc(label)}}</button></form>`}}
      function fileActions(data){{return `<div class="library-file-actions">${{actionForm(data.task_id,data.delivery_key,data.relative_path,'reveal','在 Finder 中显示')}}${{actionForm(data.task_id,data.delivery_key,data.relative_path,'open','使用系统应用打开')}}<span class="library-file-action-status" data-library-action-status></span></div>`}}
      async function submitFileAction(form){{const statusNode=form.closest('.library-file-actions').querySelector('[data-library-action-status]'),button=form.querySelector('button');button.disabled=true;statusNode.classList.remove('error');statusNode.textContent='正在打开…';try{{const response=await fetch(form.action,{{method:'POST',headers:{{Accept:'application/json'}},body:new URLSearchParams(new FormData(form))}}),data=await response.json();if(data.redirect){{location.href=data.redirect;return}}statusNode.textContent=data.error||data.notice||'操作完成';statusNode.classList.toggle('error',Boolean(data.error))}}catch(error){{statusNode.textContent='打开失败，请刷新页面后重试。';statusNode.classList.add('error')}}finally{{button.disabled=false}}}}
      async function previewFile(taskId,delivery,path,group){{previewTask(taskId,false);fileBody.innerHTML='<div class="library-preview-placeholder">正在加载交付文件…</div>';try{{const response=await fetch(`/api/library/file-preview?task_id=${{encodeURIComponent(taskId)}}&delivery=${{encodeURIComponent(delivery)}}&path=${{encodeURIComponent(path)}}`);if(!response.ok)throw new Error();const data=await response.json();fileTitle.textContent=data.name;let content='';if(data.kind==='markdown'||data.kind==='text')content=`<article class="article md">${{data.body_html||'<p>文件过大或暂时无法读取。</p>'}}</article>`;else if(data.kind==='image')content=`<div class="library-preview-media"><img src="${{esc(data.raw_url)}}" alt="${{esc(data.name)}}"></div>`;else if(data.kind==='video')content=`<div class="library-preview-media"><video src="${{esc(data.raw_url)}}" controls preload="metadata"></video></div>`;else if(data.kind==='audio')content=`<div class="library-preview-media"><audio src="${{esc(data.raw_url)}}" controls preload="metadata"></audio></div>`;else if(data.kind==='pdf')content=`<div class="library-preview-media"><iframe src="${{esc(data.raw_url)}}" title="${{esc(data.name)}}"></iframe></div>`;else content=`<div class="library-file-info"><h3>${{esc(data.name)}}</h3><div class="library-file-meta"><span>类型</span><span>${{esc(data.mime)}}</span><span>大小</span><span>${{Math.max(1,Math.round(data.size/1024)).toLocaleString()}} KB</span><span>更新时间</span><span>${{esc(data.updated_at)}}</span><span>路径</span><span>${{esc(data.relative_path)}}</span></div></div>`;fileBody.innerHTML=`${{content}}<div class="library-file-info">${{fileActions(data)}}</div>`;fileBody.querySelectorAll('form[action="/actions/open-library-item"]').forEach(form=>form.addEventListener('submit',event=>{{event.preventDefault();submitFileAction(form)}}));fileBody.querySelectorAll('[data-library-relative]').forEach(node=>node.addEventListener('click',()=>openRelative(taskId,delivery,node.dataset.libraryRelative,group)))}}catch(error){{fileBody.innerHTML='<div class="library-preview-placeholder">暂时无法预览该文件。</div>'}}}}
      async function openRelative(taskId,delivery,path,group){{const response=await fetch(`/api/library/directory?task_id=${{encodeURIComponent(taskId)}}&delivery=${{encodeURIComponent(delivery)}}&path=${{encodeURIComponent(path)}}`);response.ok?loadDirectory(taskId,delivery,path,group):previewFile(taskId,delivery,path,group)}}
      let savedSplit='';
      function togglePreviewFocus(kind,button){{const className=`focus-${{kind}}`,entering=!stack.classList.contains(className);if(entering){{savedSplit=stack.style.gridTemplateRows;stack.style.gridTemplateRows='';stack.classList.remove('focus-task','focus-file');stack.classList.add(className);button.textContent='收起'}}else{{stack.classList.remove(className);stack.style.gridTemplateRows=savedSplit;button.textContent='展开'}}}}
      function setPreviewSplit(clientY){{const rect=stack.getBoundingClientRect(),dividerHeight=7,min=100,max=rect.height-min-dividerHeight,top=Math.max(min,Math.min(max,clientY-rect.top));stack.style.gridTemplateRows=`${{top}}px ${{dividerHeight}}px minmax(0,1fr)`}}
      divider.addEventListener('pointerdown',event=>{{if(stack.classList.contains('focus-task')||stack.classList.contains('focus-file'))return;divider.setPointerCapture(event.pointerId);divider.classList.add('dragging');document.body.classList.add('library-resizing')}});divider.addEventListener('pointermove',event=>{{if(divider.hasPointerCapture(event.pointerId))setPreviewSplit(event.clientY)}});divider.addEventListener('pointerup',event=>{{if(divider.hasPointerCapture(event.pointerId))divider.releasePointerCapture(event.pointerId);divider.classList.remove('dragging');document.body.classList.remove('library-resizing')}});divider.addEventListener('keydown',event=>{{if(!['ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const rect=stack.getBoundingClientRect(),top=stack.querySelector('.library-task-pane').getBoundingClientRect().height+(event.key==='ArrowUp'?-24:24);setPreviewSplit(rect.top+top)}});
      choices.forEach(choice=>{{choice.querySelector('input').addEventListener('change',event=>{{if(selected().length>50){{event.target.checked=false;alert('单次最多选择 50 张任务卡。')}}renderGroups()}});choice.querySelector('[data-library-left-preview]').addEventListener('click',event=>{{focusedTaskId=event.currentTarget.dataset.libraryLeftPreview;renderGroups()}})}});search.addEventListener('input',scheduleSearch);filters.forEach(filter=>{{updateFilterLabel(filter);filter.querySelectorAll('input').forEach(input=>input.addEventListener('change',()=>{{updateFilterLabel(filter);scheduleSearch()}}));filter.addEventListener('toggle',()=>{{if(filter.open)filters.filter(item=>item!==filter).forEach(item=>item.removeAttribute('open'))}})}});document.addEventListener('click',event=>{{if(!event.target.closest('[data-library-filter]'))filters.forEach(filter=>filter.removeAttribute('open'))}});document.getElementById('libraryClearSelection').addEventListener('click',()=>{{choices.forEach(choice=>choice.querySelector('input').checked=false);renderGroups()}});const expandTask=document.getElementById('libraryExpandTask'),expandFile=document.getElementById('libraryExpandFile');expandTask.addEventListener('click',()=>togglePreviewFocus('task',expandTask));expandFile.addEventListener('click',()=>togglePreviewFocus('file',expandFile));scheduleSearch();renderGroups();
    }})();</script>'''
    content = content.replace('<h1>选择任务</h1>', '<h1>任务来源</h1>', 1)
    content = content.replace('id="libraryClearSelection" type="button">清空</button>', 'id="libraryClearSelection" type="button">清空固定</button>', 1)
    content = content.replace('<h2>相关文件</h2>', '<h2>交付文件</h2>', 1)
    content = content.replace(
        "choices.forEach(choice=>choice.classList.toggle('selected',choice.querySelector('input').checked));",
        "choices.forEach(choice=>{choice.classList.toggle('selected',choice.querySelector('input').checked);choice.classList.toggle('previewing',choice.querySelector('[data-library-left-preview]')?.dataset.libraryLeftPreview===focusedTaskId)});",
        1,
    )
    content = content.replace(
        '<section class="panel library-column library-preview-column"><div class="library-preview-stack"',
        '<section class="panel library-column library-preview-column"><div class="library-column-head"><h2>内容预览</h2></div><div class="library-preview-stack"',
        1,
    )
    content += '<style>.library-source-helper{margin:0;color:var(--muted);font-size:9px;line-height:1.45}.library-pin-source{display:flex;align-items:center;justify-content:center;cursor:pointer}.library-pin-source input{margin:0}.library-task-choice:has(.library-pin-source input:checked){box-shadow:inset 3px 0 0 var(--link)}.library-task-choice.previewing{outline:1px solid var(--line)}</style>'
    return runtime._layout("资料浏览", content, token)


def _render_library_package_legacy(token: str, notice: str = "", error: str = "") -> str:
    """Render a delivery-package-first, read-only library workspace."""
    packages: list[dict[str, object]] = []
    cards: list[str] = []
    for record in runtime.library_task_records():
        delivery = record.get("library_delivery") if isinstance(record.get("library_delivery"), dict) else {}
        delivery_key = str(delivery.get("key") or "")
        delivery_count = runtime.library_delivery_file_count({str(key): str(value) for key, value in delivery.items()})
        if not delivery_key or not delivery_count:
            continue
        task_id = str(record.get("task_id") or "")
        task_title = str(record.get("task_name") or record.get("title") or task_id)
        project = str(record.get("project") or "")
        project_title = runtime.task_scope_title(project, str(record.get("project_title") or ""))
        status = str(record.get("status") or "")
        delivery_state = "draft" if delivery_key == "draft" else "final"
        delivery_state_label = "草稿" if delivery_state == "draft" else "正式交付"
        delivery_name = str(delivery.get("name") or task_title)
        updated_at = runtime.format_display_time(record.get("updated_at")) or "未记录"
        updated_epoch = int(runtime.parse_sort_datetime(str(record.get("updated_at") or "")).timestamp())
        file_clues = runtime.library_delivery_file_search_clues({str(key): str(value) for key, value in delivery.items()})
        search_text = " ".join((delivery_name, task_title, task_id, project, project_title, str(record.get("description") or ""), file_clues))
        search_encoded = runtime.base64.b64encode(search_text.lower().encode("utf-8")).decode("ascii")
        packages.append({
            "task_id": task_id, "task_title": task_title, "task_status": status,
            "task_status_label": runtime.STATUS_LABEL.get(status, status), "project": project,
            "project_title": project_title, "delivery_key": delivery_key,
            "delivery_state": delivery_state, "delivery_state_label": delivery_state_label,
            "delivery_name": delivery_name, "delivery_count": delivery_count,
            "updated_at": updated_at, "updated_epoch": updated_epoch,
        })
        cards.append(
            f'<button class="library-package-card" type="button" data-library-package '
            f'data-task-id="{runtime.html.escape(task_id, quote=True)}" data-project="{runtime.html.escape(project, quote=True)}" '
            f'data-state="{delivery_state}" data-delivery="{runtime.html.escape(delivery_key, quote=True)}" data-updated="{updated_epoch}" data-search="{search_encoded}">'
            f'<span class="library-package-name">{runtime.html.escape(delivery_name)}</span>'
            f'<span class="library-package-meta">{runtime.html.escape(project_title)} · {delivery_state_label} · {delivery_count} 个文件</span>'
            f'<span class="library-package-source">来源任务 · {runtime.html.escape(task_title)} · {runtime.html.escape(task_id)} · {runtime.html.escape(runtime.STATUS_LABEL.get(status, status))}</span>'
            f'<span class="library-package-updated">更新于 {runtime.html.escape(updated_at)}</span></button>'
        )

    project_slugs = {str(item.get("project") or "") for item in packages}
    ordered_projects = [slug for slug in runtime.formal_project_slugs() if slug in project_slugs]
    ordered_projects.extend(sorted(project_slugs - set(ordered_projects)))
    project_options = "".join(f'<option value="{runtime.html.escape(slug, quote=True)}">{runtime.html.escape(runtime.task_scope_title(slug))}</option>' for slug in ordered_projects if slug)
    data_json = runtime.json.dumps(packages, ensure_ascii=False).replace("</", "<\\/")
    csrf_json = runtime.json.dumps(token, ensure_ascii=False)
    message = runtime.flash_message(notice, error)
    content = rf'''{message}
    <div class="library-layout library-delivery-layout">
      <section class="panel library-column"><div class="library-column-head"><div><h1>交付物</h1><span class="meta" id="libraryPackageCount">{len(packages)} 个交付包</span></div></div>
        <div class="library-filter-stack"><div class="search-wrap"><span class="search-icon">⌕</span><input id="libraryPackageSearch" type="search" placeholder="搜索交付包、项目、文件线索或来源任务" aria-label="搜索交付包"></div><div class="library-filter-row"><select id="libraryProjectFilter" aria-label="按项目筛选"><option value="">全部项目</option>{project_options}</select><select id="libraryStateFilter" aria-label="按交付状态筛选"><option value="">全部状态</option><option value="draft">草稿</option><option value="final">正式交付</option></select></div><select id="libraryUpdatedFilter" aria-label="按更新时间筛选"><option value="0">全部更新时间</option><option value="7">最近 7 天</option><option value="30">最近 30 天</option></select></div>
        <div class="library-package-list" id="libraryPackageList">{''.join(cards) if cards else '<div class="library-empty">暂无包含真实文件的交付包。</div>'}{'<div class="library-empty" id="libraryPackageEmpty" hidden>没有符合当前搜索和筛选条件的交付包。</div>' if cards else '<div id="libraryPackageEmpty" hidden></div>'}</div>
      </section>
      <section class="panel library-column"><div class="library-column-head"><div><h2>文件</h2><span class="meta" id="libraryFileCount">选择交付包后按需读取</span></div><button class="button ghost" id="librarySelectPackageFiles" type="button" disabled>全选当前交付包</button></div>
        <div class="library-current-package" id="libraryCurrentPackage">请选择左侧交付包。</div><div class="library-file-list" id="libraryFileList"><div class="library-empty">选择交付包后查看目录与文件。</div></div>
        <div class="library-ai-panel"><div class="library-file-selection-meta" id="libraryFileSelectionMeta">已选 0 个交付文件</div><p>可跨交付包保留选择；AI 会先接收来源，再等待你说明任务目标。</p><div class="library-ai-actions"><form method="post" action="/actions/create-task-from-deliveries" data-library-create-form data-execution-confirm data-execution-label="从交付物建立新任务"><input type="hidden" name="csrf" value="{runtime.html.escape(token, quote=True)}"><input type="hidden" name="return_to" value="/library">{runtime.execution_confirm_button("核对所选交付并建立新任务", disabled=True)}</form></div></div>
      </section>
      <section class="panel library-column library-preview-column"><div class="library-column-head"><h2 id="libraryFilePreviewTitle">内容预览</h2></div><div class="library-source-strip" id="librarySourceStrip"><span>选择交付包后显示来源。</span></div><div class="library-preview-body library-full-preview" id="libraryFilePreview"><div class="library-preview-placeholder">选择文件后查看正文或媒体内容。</div></div></section>
    </div>
    <script id="libraryData" type="application/json">{data_json}</script><script>(()=>{{
      const packages=JSON.parse(document.getElementById('libraryData').textContent),packageMap=new Map(packages.map(item=>[item.task_id+'|'+item.delivery_key,item])),csrf={csrf_json};
      const cards=[...document.querySelectorAll('[data-library-package]')],search=document.getElementById('libraryPackageSearch'),projectFilter=document.getElementById('libraryProjectFilter'),stateFilter=document.getElementById('libraryStateFilter'),updatedFilter=document.getElementById('libraryUpdatedFilter'),list=document.getElementById('libraryFileList'),fileCount=document.getElementById('libraryFileCount'),selectAll=document.getElementById('librarySelectPackageFiles'),selectionMeta=document.getElementById('libraryFileSelectionMeta'),forms=[...document.querySelectorAll('[data-library-create-form]')],previewTitle=document.getElementById('libraryFilePreviewTitle'),preview=document.getElementById('libraryFilePreview'),sourceStrip=document.getElementById('librarySourceStrip');
      const selections=new Map(),loadedFiles=new Map(),esc=value=>String(value??'').replace(/[&<>\"]/g,char=>({{'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}}[char]));
      const decode=value=>new TextDecoder().decode(Uint8Array.from(atob(value||''),character=>character.charCodeAt(0)));
      let active=null,activationVersion=0,previewVersion=0;
      function packageKey(item){{return item.task_id+'|'+item.delivery_key}}function selectionKey(value){{return JSON.stringify(value)}}
      function filterPackages(){{const terms=search.value.trim().toLowerCase().split(/\s+/).filter(Boolean),days=Number(updatedFilter.value||0),threshold=days?Date.now()/1000-days*86400:0;let visible=0;cards.forEach(card=>{{const searchableText=decode(card.dataset.search),show=terms.every(term=>searchableText.includes(term))&&(!projectFilter.value||card.dataset.project===projectFilter.value)&&(!stateFilter.value||card.dataset.state===stateFilter.value)&&(!threshold||Number(card.dataset.updated)>=threshold);card.hidden=!show;if(show)visible++}});document.getElementById('libraryPackageCount').textContent=`${{visible}} 个交付包`;document.getElementById('libraryPackageEmpty').hidden=visible!==0}}
      function syncSelection(){{selectionMeta.textContent=`已选 ${{selections.size}} 个交付文件`;forms.forEach(form=>{{form.querySelectorAll('input[name="selection"]').forEach(input=>input.remove());selections.forEach(value=>{{const input=document.createElement('input');input.type='hidden';input.name='selection';input.value=JSON.stringify(value);form.appendChild(input)}});form.querySelector('button').disabled=!selections.size}});list.querySelectorAll('[data-library-file-check]').forEach(input=>input.checked=selections.has(input.dataset.selectionKey));if(active){{const entries=loadedFiles.get(packageKey(active))||[],allSelected=entries.length&&entries.every(entry=>selections.has(selectionKey({{task_id:active.task_id,delivery:active.delivery_key,path:entry.relative_path}})));selectAll.textContent=allSelected?'取消选择当前包':'全选当前交付包'}}}}
      function sourceBar(item){{sourceStrip.innerHTML=`<span><strong>${{esc(item.project_title)}}</strong> ／ ${{esc(item.delivery_state_label)}} ／ 来源任务：${{esc(item.task_title)}}</span><a class="button ghost" href="/tasks/${{encodeURIComponent(item.task_id)}}">查看任务卡</a>`}}
      function fileIcon(entry){{return entry.suffix==='.md'?'M':['.png','.jpg','.jpeg','.webp','.gif'].includes(entry.suffix)?'◇':['.mp4','.mov','.m4v','.webm'].includes(entry.suffix)?'▶':entry.suffix==='.pdf'?'P':'·'}}
      function selectedFiles(){{const values=[];selections.forEach((value,key)=>{{const item=packageMap.get(value.task_id+'|'+value.delivery),entries=loadedFiles.get(value.task_id+'|'+value.delivery)||[],entry=entries.find(candidate=>candidate.relative_path===value.path);if(item&&entry)values.push({{key,value,item,entry}})}});return values}}
      function fileRow(item,entry,pinned=false){{const value={{task_id:item.task_id,delivery:item.delivery_key,path:entry.relative_path}},key=selectionKey(value),parent=entry.relative_path.includes('/')?entry.relative_path.split('/').slice(0,-1).join('/'):'交付包根目录',detail=pinned?`${{item.delivery_name}} ／ ${{parent}}`:parent;return `<div class="library-file-row${{pinned?' pinned':''}}" data-file-package="${{esc(packageKey(item))}}" data-file-path="${{esc(entry.relative_path)}}"><input type="checkbox" data-library-file-check data-selection-key="${{esc(key)}}" aria-label="选择 ${{esc(entry.name)}}"><span class="library-node-icon">${{fileIcon(entry)}}</span><button type="button" data-library-file-preview data-package-key="${{esc(packageKey(item))}}" data-path="${{esc(entry.relative_path)}}"><strong>${{esc(entry.name)}}</strong><small>${{esc(detail)}}</small></button></div>`}}
      function renderWorkspace(item,entries,mode='ready'){{const pinned=selectedFiles(),pinnedHtml=pinned.length?`<section class="library-file-section pinned-files"><div class="library-file-section-head"><span>已选交付文件</span><span>${{pinned.length}} 个 · 跨交付包保留</span></div>${{pinned.map(value=>fileRow(value.item,value.entry,true)).join('')}}</section>`:'',currentBody=mode==='loading'?'<div class="library-empty">正在读取当前交付包…</div>':mode==='error'?'<div class="library-empty">暂时无法读取这个交付包（网络或服务异常）。这不是空交付包，请稍后重试。</div>':entries.length?entries.map(entry=>fileRow(item,entry)).join(''):'<div class="library-empty">交付包中没有可浏览文件。</div>',currentHtml=`<section class="library-file-section current-files"><div class="library-file-section-head"><span>当前交付包</span><span>${{esc(item.delivery_name)}} · ${{entries.length}} 个文件</span></div>${{currentBody}}</section>`;list.innerHTML=pinnedHtml+currentHtml;fileCount.textContent=`${{entries.length}} 个文件 · 已选 ${{selections.size}}`;selectAll.disabled=mode!=='ready'||!entries.length;bindWorkspace();syncSelection()}}
      function bindWorkspace(){{list.querySelectorAll('[data-library-file-check]').forEach(input=>input.addEventListener('change',()=>{{const value=JSON.parse(input.dataset.selectionKey);input.checked?selections.set(input.dataset.selectionKey,value):selections.delete(input.dataset.selectionKey);renderWorkspace(active,loadedFiles.get(packageKey(active))||[],loadedFiles.has(packageKey(active))?'ready':'loading')}}));list.querySelectorAll('[data-library-file-preview]').forEach(button=>button.addEventListener('click',()=>{{const item=packageMap.get(button.dataset.packageKey);if(item)previewFile(item,button.dataset.path)}}))}}
      function resetPreview(message='选择文件后查看正文或媒体内容。'){{previewVersion++;previewTitle.textContent='内容预览';preview.innerHTML=`<div class="library-preview-placeholder">${{message}}</div>`}}
      function previewActivePackage(item,entries){{if(!entries.length){{resetPreview('当前交付包没有可预览文件。');return}}const selected=entries.find(entry=>selections.has(selectionKey({{task_id:item.task_id,delivery:item.delivery_key,path:entry.relative_path}}))),latest=[...entries].sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at)))[0];previewFile(item,(selected||latest).relative_path)}}
      async function activate(item){{active=item;const version=++activationVersion,key=packageKey(item);cards.forEach(card=>card.classList.toggle('active',card.dataset.taskId===item.task_id&&card.dataset.state===item.delivery_state));sourceBar(item);document.getElementById('libraryCurrentPackage').textContent=`当前浏览 · ${{item.delivery_name}} · ${{item.project_title}} · ${{item.delivery_state_label}}`;const cached=loadedFiles.get(key);if(cached){{renderWorkspace(item,cached);previewActivePackage(item,cached);return}}renderWorkspace(item,[],'loading');resetPreview('正在切换到当前交付包预览…');try{{const response=await fetch(`/api/library/directory?task_id=${{encodeURIComponent(item.task_id)}}&delivery=${{encodeURIComponent(item.delivery_key)}}&flat=1`);if(!response.ok)throw new Error();const entries=(await response.json()).entries||[];loadedFiles.set(key,entries);if(version!==activationVersion||packageKey(active)!==key)return;renderWorkspace(item,entries);previewActivePackage(item,entries)}}catch(error){{if(version!==activationVersion||packageKey(active)!==key)return;renderWorkspace(item,[],'error');resetPreview('暂时无法读取当前交付包（网络或服务异常）。这不是空交付包，请稍后重试。')}}}}
      function actionForm(data,mode,label){{return `<form method="post" action="/actions/open-library-item"><input type="hidden" name="csrf" value="${{esc(csrf)}}"><input type="hidden" name="return_to" value="/library"><input type="hidden" name="task_id" value="${{esc(data.task_id)}}"><input type="hidden" name="delivery" value="${{esc(data.delivery_key)}}"><input type="hidden" name="path" value="${{esc(data.relative_path)}}"><input type="hidden" name="mode" value="${{mode}}"><button class="button ghost" type="submit">${{label}}</button></form>`}}
      async function previewFile(item,path){{const version=++previewVersion;list.querySelectorAll('.library-file-row').forEach(row=>row.classList.toggle('previewing',row.dataset.filePackage===packageKey(item)&&row.dataset.filePath===path));previewTitle.textContent=path.split('/').pop()||'内容预览';preview.innerHTML='<div class="library-preview-placeholder">正在加载文件…</div>';try{{const response=await fetch(`/api/library/file-preview?task_id=${{encodeURIComponent(item.task_id)}}&delivery=${{encodeURIComponent(item.delivery_key)}}&path=${{encodeURIComponent(path)}}`);if(!response.ok)throw new Error();const data=await response.json();if(version!==previewVersion)return;let body='';if(data.kind==='markdown'||data.kind==='text')body=`<article class="article md">${{data.body_html||'<p>文件过大或暂时无法读取。</p>'}}</article>`;else if(data.kind==='image')body=`<div class="library-preview-media"><img src="${{esc(data.raw_url)}}" alt="${{esc(data.name)}}"></div>`;else if(data.kind==='video')body=`<div class="library-preview-media"><video src="${{esc(data.raw_url)}}" controls preload="metadata"></video></div>`;else if(data.kind==='audio')body=`<div class="library-preview-media"><audio src="${{esc(data.raw_url)}}" controls preload="metadata"></audio></div>`;else if(data.kind==='pdf')body=`<div class="library-preview-media"><iframe src="${{esc(data.raw_url)}}" title="${{esc(data.name)}}"></iframe></div>`;else body=`<div class="library-file-info"><h3>${{esc(data.name)}}</h3><div class="library-file-meta"><span>类型</span><span>${{esc(data.mime)}}</span><span>大小</span><span>${{Math.max(1,Math.round(data.size/1024)).toLocaleString()}} KB</span><span>路径</span><span>${{esc(data.relative_path)}}</span></div></div>`;preview.innerHTML=body+`<div class="library-file-actions">${{actionForm(data,'reveal','Finder 中显示')}}${{actionForm(data,'open','系统应用打开')}}</div>`}}catch(error){{if(version===previewVersion)preview.innerHTML='<div class="library-preview-placeholder">暂时无法预览该文件（网络或服务异常）。这不是空文件，请稍后重试。</div>'}}}}
      selectAll.addEventListener('click',()=>{{if(!active)return;const entries=loadedFiles.get(packageKey(active))||[],values=entries.map(entry=>{{const value={{task_id:active.task_id,delivery:active.delivery_key,path:entry.relative_path}};return [selectionKey(value),value]}}),allSelected=values.length&&values.every(([key])=>selections.has(key));values.forEach(([key,value])=>allSelected?selections.delete(key):selections.set(key,value));renderWorkspace(active,entries)}});
      cards.forEach(card=>card.addEventListener('click',()=>activate(packageMap.get(card.dataset.taskId+'|'+card.dataset.delivery))));[search,projectFilter,stateFilter,updatedFilter].forEach(control=>control.addEventListener(control===search?'input':'change',filterPackages));filterPackages();syncSelection();const first=cards.find(card=>!card.hidden);if(first)first.click();
    }})();</script>'''
    return runtime._layout("资料浏览", content, token)


def render_library(token: str, notice: str = "", error: str = "") -> str:
    """Render the file-first delivery/input material browser."""
    materials = runtime.cached_library_material_records()
    delivery_count = sum(1 for item in materials if item.get("kind") == "delivery")
    projects = sorted({str(item.get("project") or "") for item in materials if item.get("project")})
    page = {
        "materials": materials, "counts": {"delivery": delivery_count, "input": len(materials) - delivery_count},
        "projects": [(slug, runtime.task_scope_title(slug)) for slug in projects],
        "forms": runtime.library_material_forms(token, "/library"),
        "browser": {"csrf": token, "return_to": "/library", "controller": "", "sync_url": True},
    }
    content = runtime.flash_message(notice, error) + runtime.library_page.render(page) + f'<script src="/assets/library.js?v={runtime.LIBRARY_VERSION}"></script>'
    return runtime._layout("资料浏览", content, token)
